raw_text:
{
  "verifications": [
    {
      "fact_id": "F01",
      "verdict": "VERIFIED",
      "verification_notes": "LINE Digital Frontierの発表は2026年10月19日12時で、LINEマンガ上のbyUsを「リリースしました」と記載。ITmediaも10月19日に公開したと報じており、発表日と提供開始の記述は整合する。([prtimes.jp](https://prtimes.jp/main/html/rd/p/000000536.000063705.html))"
    },
    {
      "fact_id": "F02",
      "verdict": "VERIFIED",
      "verification_notes": "会社発表は、ユーザーが原作ストーリーの主人公となり、キャラクターとの交流を通じ新たなストーリーを作るサービスと説明。ITmediaも会話を通じて自分だけの物語を作れると報じている。原作の正史を書き換える機能までは確認できないという注記も妥当。([prtimes.jp](https://prtimes.jp/main/html/rd/p/000000536.000063705.html))"
    },
    {
      "fact_id": "F03",
      "verdict": "VERIFIED",
      "verification_notes": "会社発表は取り扱いを原作者が承認した公式IPに限定すると記載。LINEマンガのヘルプも、byUsに登場するオリジナル作品は原作作家との正式契約を通じて使用許可を得ているとしており、別の表現で権利許諾条件を確認できる。([prtimes.jp](https://prtimes.jp/main/html/rd/p/000000536.000063705.html))"
    },
    {
      "fact_id": "F04",
      "verdict": "VERIFIED",
      "verification_notes": "会社発表の表現は「オリジナル・独占配信作品」、ヘルプの表現は「LINEマンガオリジナル作品」。Factはそれぞれの記載を区別しており、両者の対象範囲が同一だとは断定していない。対象範囲の同一性が資料から確定できないとの注記も適切。([prtimes.jp](https://prtimes.jp/main/html/rd/p/000000536.000063705.html))"
    },
    {
      "fact_id": "F05",
      "verdict": "VERIFIED",
      "verification_notes": "会社発表は、原作の世界観とキャラクター設定をもとに構成された序盤以降、ユーザーがキャラクターと会話して物語を展開すると説明。Factの要約はこの説明に沿っている。([prtimes.jp](https://prtimes.jp/main/html/rd/p/000000536.000063705.html))"
    },
    {
      "fact_id": "F06",
      "verdict": "VERIFIED",
      "verification_notes": "会社発表およびITmediaは、ファンストーリーで原作キャラクターを基盤に状況や関係性を設定でき、作成したストーリーを他ユーザーに公開することも可能と説明。公開が任意であるというFactの整理も正確。([prtimes.jp](https://prtimes.jp/main/html/rd/p/000000536.000063705.html))"
    },
    {
      "fact_id": "F07",
      "verdict": "VERIFIED",
      "verification_notes": "会社発表は既存のキャラチャットとの違いを、会話に加えて自由度の高い二次創作ストーリーを作れる点と説明し、ITmediaも同趣旨を報じている。終了・統合・置き換えを示す記載は確認できず、その点の注記も適切。([prtimes.jp](https://prtimes.jp/main/html/rd/p/000000536.000063705.html))"
    },
    {
      "fact_id": "F08",
      "verdict": "VERIFIED",
      "verification_notes": "会社発表は第1弾として2作品からジョイ、エスター、橘蓮、百谷玲央の4人を実装したと記載。ITmediaも2作品・計4人と報じている。([prtimes.jp](https://prtimes.jp/main/html/rd/p/000000536.000063705.html))"
    },
    {
      "fact_id": "F09",
      "verdict": "VERIFIED",
      "verification_notes": "発表はLINEマンガアプリが必要で、LINEログインおよびアプリver26.10.10以上が利用条件と記載。アプリ内クイックメニューから利用できるとの案内も確認できる。利用可能地域の網羅的な範囲までは、これらの記載から確定できない。([prtimes.jp](https://prtimes.jp/main/html/rd/p/000000536.000063705.html))"
    },
    {
      "fact_id": "F10",
      "verdict": "VERIFIED",
      "verification_notes": "会社発表は毎日ログインで無料チケットを獲得でき、マンガコインでもトークできると記載。ITmediaは各ストーリーの冒頭3ターンが無料と報道し、LINEマンガのヘルプも「ストーリーごとの冒頭3ターン」と無料チケットによる利用を案内している。3ターン無料とチケットの説明を分けたFactの整理は妥当。([prtimes.jp](https://prtimes.jp/main/html/rd/p/000000536.000063705.html))"
    },
    {
      "fact_id": "F11",
      "verdict": "VERIFIED",
      "verification_notes": "会社発表は韓国NAVER WEBTOONで2026年6月にリリースし、開始10週間で累計1,400万件の会話と報告。韓国の報道も同じ数字を伝えている。会話件数であり利用者数ではないというscopeの区別も正しい。([prtimes.jp](https://prtimes.jp/main/html/rd/p/000000536.000063705.html))"
    },
    {
      "fact_id": "F12",
      "verdict": "VERIFIED",
      "verification_notes": "会社発表はサービスリリース前後1週間の比較で、実装作品が休載中にもかかわらず原作閲覧数が67％増加したと報告し、韓国報道も同数値を伝えている。集計方法や対象作品数は資料に示されず、観察された前後比較として扱い因果を断定しない注記が適切。([prtimes.jp](https://prtimes.jp/main/html/rd/p/000000536.000063705.html))"
    },
    {
      "fact_id": "F13",
      "verdict": "AMBIGUOUS",
      "verification_notes": "会社発表と韓国報道は、リリース前後各1週間の比較で新規利用者が105％増加したと報告しており、数値自体は確認できる。一方、「新規利用者」が原作作品の新規読者なのか、サービス利用者なのかなど、対象・定義・集計単位は資料で明確でない。Factが実装作品に関する比較として限定している点はよいが、母集団をこれ以上特定するのは避けるべき。([prtimes.jp](https://prtimes.jp/main/html/rd/p/000000536.000063705.html))"
    },
    {
      "fact_id": "F14",
      "verdict": "VERIFIED",
      "verification_notes": "発表は日本向け第1弾の2作品・4キャラクターを実装済みとし、Official Storyでの会話による展開、ファンストーリーの創作と他ユーザーへの公開可能性を説明している。ヘルプもオフィシャルストーリーとユーザーストーリーの2種類を確認できる。したがって「発表時点の案内範囲」としては裏付けられるが、全作品で利用可能、原作の正史を変更可能、または選択肢・分岐数まで定められているとは確認できない。([prtimes.jp](https://prtimes.jp/main/html/rd/p/000000536.000063705.html))"
    }
  ]
}
